import os
import json

def validate_file_exists(file_path):
    return os.path.isfile(file_path)

def validate_file_not_empty(file_path):
    return os.path.getsize(file_path) > 0

def main():
    validation_summary = []

    # Define the files to check
    files_to_check = {
        'outputs/t01_selected_indicators.csv': ['Indicator file exists', 'Indicator file is not empty'],
        'outputs/t05_clean_stops.csv': ['Clean stops file exists', 'Clean stops file is not empty'],
        'outputs/t08_pois_clean.csv': ['POIs clean file exists', 'POIs clean file is not empty'],
        'outputs/t10_accessibility_scores.csv': ['Accessibility scores file exists', 'Accessibility scores file is not empty'],
        'outputs/t13_city_clusters.csv': ['City clusters file exists', 'City clusters file is not empty']
    }

    for file_path, checks in files_to_check.items():
        for check in checks:
            file_exists = validate_file_exists(file_path)
            file_not_empty = validate_file_not_empty(file_path) if file_exists else False

            if check == 'Indicator file exists':
                passed = file_exists
            elif check == 'Indicator file is not empty':
                passed = file_not_empty
            elif check == 'Clean stops file exists':
                passed = file_exists
            elif check == 'Clean stops file is not empty':
                passed = file_not_empty
            elif check == 'POIs clean file exists':
                passed = file_exists
            elif check == 'POIs clean file is not empty':
                passed = file_not_empty
            elif check == 'Accessibility scores file exists':
                passed = file_exists
            elif check == 'Accessibility scores file is not empty':
                passed = file_not_empty
            elif check == 'City clusters file exists':
                passed = file_exists
            elif check == 'City clusters file is not empty':
                passed = file_not_empty

            validation_summary.append({
                'check_name': check,
                'passed': passed,
                'message': f"Check passed: {passed}" if passed else f"Check failed: {file_path} is missing or empty"
            })

    # Write the validation summary to the JSON file
    with open('outputs/t14_validation_summary.json', 'w') as summary_file:
        json.dump(validation_summary, summary_file, indent=4)

if __name__ == "__main__":
    main()
